SELECT g.id, g.name_original, g.confidence_score, (SELECT count(*) FROM sources s WHERE s.entity_id=g.id) AS n_src FROM geo_entities g WHERE g.id IN (165, 568, 573, 579, 691, 715, 837, 838, 851, 1027) ORDER BY g.id;
